using EduCenterManagement.Repositories;using EduCenterManagement.Services.Common;using EduCenterManagement.ViewModels.ParentChildren;namespace EduCenterManagement.Services;public sealed class ParentChildrenService(ICurrentUserContext current,IParentChildrenRepository repo):IParentChildrenService{public async Task<ParentChildrenViewModel?> GetChildrenAsync(CancellationToken ct=default)=>await current.GetParentProfileIdAsync(ct) is int p?await repo.GetChildrenAsync(p,ct):null;public async Task<ChildDetailsViewModel?> GetDetailsAsync(int s,CancellationToken ct=default)=>await current.GetParentProfileIdAsync(ct) is int p?await repo.GetDetailsAsync(p,s,ct):null;public async Task<AttendancePageViewModel?> GetAttendanceAsync(int studentId,int? classId,int page,CancellationToken ct=default)=>await current.GetParentProfileIdAsync(ct) is int p?await repo.GetAttendanceAsync(p,studentId,classId,Math.Max(1,page),10,ct):null;}